import os
import matplotlib.pyplot as plt
import pandas as pd

# Load CSV output generated by perf_analyzer
csv_file = "sla_benchmark_results.csv"

if not os.path.exists(csv_file):
    print(f"Error: '{csv_file}' not found. Run perf_analyzer first.")
    exit(1)

df = pd.read_csv(csv_file)

# Normalize column headers (strip spaces)
df.columns = df.columns.str.strip()

# Detect Concurrency and P99 Latency columns
concurrency_col = [col for col in df.columns if "concurrency" in col.lower()][0]
p99_col = [col for col in df.columns if "p99" in col.lower()][0]

# perf_analyzer outputs latency in microseconds (usec); convert to milliseconds (ms)
if "usec" in p99_col.lower() or df[p99_col].mean() > 500:
    df["p99_ms"] = df[p99_col] / 1000.0
else:
    df["p99_ms"] = df[p99_col]

# Sort sequentially by concurrency level
df = df.sort_values(by=concurrency_col)

# Configure plot aesthetic
plt.figure(figsize=(10, 6), dpi=120)

plt.plot(
    df[concurrency_col],
    df["p99_ms"],
    marker="o",
    linewidth=2.5,
    color="#0066cc",
    label="P99 Latency",
)

# SLA Limit visual marker (50 ms)
sla_limit = 50.0
plt.axhline(
    y=sla_limit,
    color="#d9534f",
    linestyle="--",
    linewidth=1.5,
    label=f"SLA Threshold ({sla_limit:.0f} ms)",
)

# Annotate data points with exact values
for _, row in df.iterrows():
    c_val = int(row[concurrency_col])
    p99_val = row["p99_ms"]
    plt.annotate(
        f"{p99_val:.1f} ms",
        (c_val, p99_val),
        textcoords="offset points",
        xytext=(0, 8),
        ha="center",
        fontsize=9,
    )

# Axis labels and graph details
plt.title(
    "vector_vision_general_v1 — P99 Latency vs Concurrency",
    fontsize=14,
    fontweight="bold",
    pad=15,
)
plt.xlabel("Concurrency Level (c)", fontsize=11, fontweight="bold")
plt.ylabel("P99 Latency (ms)", fontsize=11, fontweight="bold")
plt.xticks(df[concurrency_col])
plt.grid(True, linestyle=":", alpha=0.6)
plt.legend(loc="upper left", fontsize=10)
plt.tight_layout()

# Save image locally
output_plot = "p99_latency_vs_concurrency.png"
plt.savefig(output_plot, dpi=300)
print(f"Benchmark chart saved to: {output_plot}")
plt.show()